contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: amount to collect
    function run(uint collectAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (collectAmt)); require(collectAmt <= 1000000000000000000000000000000);
        // Ensure this test contract has enough ETH to fund a prior Deposit call
        // so that balances[msg.sender] can be >= collectAmt when calling Collect.
        // We require enough balance to call Deposit with collectAmt.
        require(address(this).balance >= collectAmt);

        // Make sure c has its Log and MinSum settable before initialization: caller should be allowed to set them.
        // (These calls may revert if c was already initialized by some other interaction; in the fresh deployment they won't.)
        // We don't care about their effects except to allow Deposit/Collect behavior to be typical.
        // Set MinSum to 0 so Collect condition depends only on sufficient balance.
        // These setup calls are top-level and change c's state.
        c.SetMinSum(0); if (__ESBMC_reverted()) return;

        // Deposit collectAmt into c from this contract so that this contract becomes the depositor
        c.Deposit{value: collectAmt}(); if (__ESBMC_reverted()) return;

        // Read balance before Collect via public getter
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        // Read c's Ether balance before
        uint beforeCbal = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        c.Collect(collectAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterCbal = address(c).balance;

        // General rule: If Collect did not revert then the depositor's recorded balance decreased by exactly collectAmt
        // and the contract's Ether balance decreased by at least collectAmt (the transfer might fail partially but Collect requires success or reverts).
        // If Collect reverted, no claim is made.
        assert(reverted || (beforeBal >= collectAmt && beforeBal - afterBal == collectAmt && beforeCbal >= afterCbal && beforeCbal - afterCbal >= collectAmt));
    }

    // Allow the contract to receive Ether so c.call can send to this contract during Collect
    receive() external payable {}
}

