// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 collectAmt) internal {
        collectAmt = bound(collectAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= collectAmt);
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: collectAmt}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        uint beforeCbal = address(c).balance;
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        uint afterCbal = address(c).balance;
        assertTrue(reverted || (beforeBal >= collectAmt && beforeBal - afterBal == collectAmt && beforeCbal >= afterCbal && beforeCbal - afterCbal >= collectAmt));
    }

    function testFuzz_run(uint256 collectAmt) public {
        _run(collectAmt);
    }

    receive() external payable {}
}
